/**
 * @summary Get a subscription
 */

export function useGetSubscription<TData = Awaited<ReturnType<typeof getSubscription>>, TError = ErrorModel>(
 id: string, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof getSubscription>>, TError, TData>>, request?: SecondParameter<typeof fetcher>}
 , queryClient?: QueryClient
 ):  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {

  const queryOptions = getGetSubscriptionQueryOptions(id,options)

  const query = useQuery(queryOptions, queryClient) as  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> };

  return withQueryKey(query, queryOptions.queryKey);
}







export const getSpendingSummaryUrl = () => {




  return `/api/v1/summary`
}

/**
 * Monthly and yearly recurring spend per currency, spend per category and payment method, how much to set aside each month for yearly bills, what is due before the next payday, and the charges of the next 7 days.
 * @summary Spending summary
 */
export const spendingSummary = async ( options?: Parameters<typeof fetcher>[1]): Promise<SpendingSummary> => {

  return fetcher<SpendingSummary>(getSpendingSummaryUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getSpendingSummaryQueryKey = () => {
    return [
    `/api/v1/summary`
    ] as const;
    }


export const getSpendingSummaryQueryOptions = <TData = Awaited<ReturnType<typeof spendingSummary>>, TError = ErrorModel>( options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof spendingSummary>>, TError, TData>>, request?: SecondParameter<typeof fetcher>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getSpendingSummaryQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof spendingSummary>>> = ({ signal }) => spendingSummary({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof spendingSummary>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

